.radio{
  display:inline-flex;
  align-items:center;
  gap:var(--s-2);
  cursor:pointer;
  font-size:var(--t-small);
  color:var(--obsidian-100);
}
.radio input{
  appearance:none;
  width:var(--s-4);
  height:var(--s-4);
  border:var(--bw-1) solid var(--border-input);
  border-radius:var(--r-full);
  background:var(--surface-field);
  display:grid;
  place-items:center;
  transition:border-color var(--d-quick) var(--ease-standard), background var(--d-quick) var(--ease-standard);
}
.radio input:checked{
  border-color:var(--primary-500);
}
.radio input:checked::after{
  content:"";
  width:8px;
  height:8px;
  border-radius:var(--r-full);
  background:var(--primary-500);
}
.radio input:focus-visible{
  outline:var(--focus-width) solid var(--obsidian-100);
  outline-offset:var(--focus-offset);
  box-shadow:var(--ring-halo);
}
.radio input:disabled{
  opacity:0.4;
  cursor:not-allowed;
}
.radio:has(input:disabled){
  color:var(--obsidian-400);
  cursor:not-allowed;
}
